import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        return 0
    try:
        if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        else:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
    except requests.RequestException as e:
        raise
    tree = html.fromstring(content)
    table = tree.xpath("//table")
    if not table:
        return 0
    table = table[0]
    header_elements = table.xpath(".//tr[th]")
    headers = []
    if header_elements:
        headers = [h.text_content().strip() for h in header_elements[0].xpath(".//th")]
    rows = []
    for row in table.xpath(".//tr"):
        cells = row.xpath(".//td")
        if not cells:
            continue
        row_data = [c.text_content().strip() for c in cells]
        rows.append(row_data)
    if not rows:
        return 0
    if headers and len(headers) == len(rows[0]):
        df = pd.DataFrame(rows, columns=headers)
    else:
        df = pd.DataFrame(rows)
    if df.empty:
        return 0
    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
        finally:
            conn.close()
    except sqlite3.DatabaseError as e:
        raise
    return len(df)
