import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url:
        raise ValueError("URL must be a non-empty string")
    if not isinstance(destination_directory, str) or not destination_directory:
        raise ValueError("Destination directory must be a non-empty string")
    if headers is None:
        headers = {}
    os.makedirs(destination_directory, exist_ok=True)
    temp_zip_path = os.path.join(destination_directory, "downloaded_archive.zip")
    response = None
    try:
        verify_cert = not ("localhost" in url or "127.0.0.1" in url)
        response = requests.get(url, headers=headers, stream=True, timeout=30, verify=verify_cert)
        response.raise_for_status()
        with open(temp_zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        if os.path.exists(temp_zip_path):
            try:
                os.remove(temp_zip_path)
            except OSError:
                pass
        raise ConnectionError(f"Failed to download ZIP file from {url}: {e}")
    finally:
        if response is not None:
            response.close()
    extracted_files = []
    try:
        with zipfile.ZipFile(temp_zip_path, "r") as zip_ref:
            zip_ref.extractall(destination_directory)
            for member in zip_ref.namelist():
                normalized = os.path.normpath(member)
                if normalized.endswith(os.sep):
                    continue
                extracted_files.append(normalized)
    except zipfile.BadZipFile as e:
        raise ValueError(f"Downloaded file is not a valid ZIP archive: {e}")
    finally:
        if os.path.exists(temp_zip_path):
            try:
                os.remove(temp_zip_path)
            except OSError:
                pass
    return extracted_files
