```python
import re
import requests
import json
import csv
import os  
API_URL = 'https://api.example.com/data'
def task_func(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ValueError("Pattern must be a non-empty string.")
    regex = re.compile(pattern)
    try:
        response = requests.get(API_URL)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to fetch data from API: {e}")
    try:
        payload = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Response is not valid JSON: {e}")
    if "data" not in payload:
        data_items = []
    else:
        raw_data = payload["data"]
        if isinstance(raw_data, str):
            data_items = [raw_data]
        elif isinstance(raw_data, (list, tuple)):
            data_items = [str(item) for item in raw_data]
        else:
            data_items = [str(raw_data)]
    matches = []
    for item in data_items:
        found = regex.findall(item)
        if isinstance(found, list):
            for f in found:
                if isinstance(f, tuple):
                    matches.extend([g for g in f if g])
                else:
                    matches.append(f)
    csv_filename = "matched_data.csv"
    csv_path = os.path.abspath(csv_filename)
    with open(csv_path, "w", newline="") as f:
        writer = csv.writer(f)
        for m in matches:
            writer.writerow([m])
    return csv_path
```

